// TALENTS 6 – Export (Stefan 18.10.2026), Migration 46: Sitzung aus dem Cookie wie ALLY 8, Umfang aus der Adresse (talent=<id> oder talent=alle).
// Recht „Talents verwalten“ bzw. Admin und gültige Talents prüft die Datenbank (talents_export_start). Dieser Ablauf speichert keine Ausführungsdaten
// (der Export enthält personenbezogene Daten).
const h = $json.headers || {}, q = $json.query || {};
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const t = String(q.talent ?? '').trim();
// Ungültig oder fehlend: 'unbekannt' (die Datenbank meldet "Unbekanntes Talent"; leer hieße dort "alle")
const talent = /^([0-9]{1,9}|alle)$/.test(t) ? t : 'unbekannt';
return [{ json: { token, talent } }];

// Export: Seiten planen (Stefan 18.10.2026). Eingang: Ergebnis von talents_export_start($token, $talent) als json.r.
// Ausgang: je Teil und Seite ein Eintrag für talents_export_teil; bei Fehler ein Eintrag mit fehler (Antwort ohne Datei).
const r = $input.first().json.r || {};
if (r.ok !== true) return [{ json: { ok: false, angemeldet: r.angemeldet === true, fehler: String(r.fehler || 'Der Export ist nicht möglich.') } }];
const talent = r.umfang === 'talent' ? String(r.talent_id) : 'alle';
const out = [];
for (const t of Array.isArray(r.teile) ? r.teile : []) {
  const seiten = Math.max(1, Number(t.seiten) || 1);
  for (let s = 1; s <= seiten; s++) out.push({ json: { ok: true, talent, teil: String(t.teil), seite: s } });
}
return out;

// Export: CSV-Dateien und LIESMICH.txt bauen (Stefan 18.10.2026). Format wie talents_csv in der Datenbank:
// UTF-8 mit BOM, Trennzeichen Semikolon, jedes Feld in Anführungszeichen, "" für ", Zeilenende CRLF;
// Texte, die mit = + - @ beginnen und keine Zahl sind, bekommen ein vorangestelltes ' (Schutz vor Formeln).
// Eingang: alle Ergebnisse von talents_export_teil (json.r) und der Plan aus "Export starten" (json.r von talents_export_start).
const plan = $('Export starten').first().json.r;
const feld = v => {
  let s = v === null || v === undefined ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
  if (/^[=+@-]/.test(s) && !/^-?[0-9]+(\.[0-9]+)?$/.test(s)) s = "'" + s;
  return '"' + s.split('"').join('""') + '"';
};
const teile = {};
for (const it of $input.all()) {
  const r = it.json.r || {};
  if (r.ok !== true) throw new Error('Export: ' + String(r.fehler || 'Teil nicht lesbar').slice(0, 200));
  const t = teile[r.teil] = teile[r.teil] || { datei: r.datei, spalten: r.spalten, seiten: {} };
  t.seiten[r.seite] = r.zeilen || [];
}
const dateien = [];
for (const p of plan.teile) {
  const t = teile[p.teil] || { datei: p.datei, spalten: p.spalten.map(s => s.name), seiten: {} };
  const zeilen = [];
  for (const s of Object.keys(t.seiten).map(Number).sort((a, b) => a - b)) zeilen.push(...t.seiten[s]);
  if (zeilen.length !== Number(p.anzahl)) throw new Error('Export: ' + p.datei + ' hat ' + zeilen.length + ' statt ' + p.anzahl + ' Zeilen. Bitte erneut exportieren.');
  const text = '﻿' + [t.spalten.map(feld).join(';')].concat(zeilen.map(z => z.map(feld).join(';'))).join('\r\n') + '\r\n';
  dateien.push({ name: p.datei, text });
}
dateien.push({ name: plan.beschreibung_datei, text: '﻿' + plan.beschreibung });
// je Datei ein Binäreintrag (für den Knoten "Compression", zip)
return [{ json: { dateiname: plan.dateiname, anzahl: dateien.length },
  binary: Object.fromEntries(dateien.map((d, i) => ['datei_' + i, { data: Buffer.from(d.text, 'utf8').toString('base64'), mimeType: d.name.endsWith('.txt') ? 'text/plain' : 'text/csv', fileName: d.name }])) }];

// Zurück zur Seite (Stefan 18.10.2026): Export nicht möglich. Die Meldung steht schon in der Sitzung ("Meldung setzen");
// ohne gültige Sitzung zur Anmeldung. Rücksprung auf Einstellungen › Talents (beim Talent mit dessen Ansicht).
const SEITE = '/webhook/web';
const A = $('Anfrage lesen').first().json;
const p = $('Seiten planen').first().json || {};
if (p.angemeldet !== true || !A.token) return [{ json: { ziel: SEITE + '?m=abgelaufen', set_cookie: 'ally_sitzung=; Path=' + SEITE + '; Max-Age=0; HttpOnly; Secure; SameSite=None' } }];
return [{ json: { ziel: SEITE + '?ansicht=einstellungen&bereich=talents' + (/^[0-9]{1,9}$/.test(A.talent) ? '&talent=' + A.talent : ''), set_cookie: '' } }];
